/// <summary>
/// Service class that implements the business logic for the con demo job history scan operation.
/// </summary>
public class ConDemoJobHistoryScanService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Counts the batch job history records selected by the packed query of the contract.
/// </summary>
/// <param name = "_contract">The contract carrying the packed query.</param>
public void scanHistory(ConDemoJobHistoryScanContract _contract)
{
    Query               query;
    QueryRun            queryRun;
    BatchJobHistory     batchJobHistory;
    int                 matched;

    query = new Query(SysOperationHelper::base64Decode(_contract.parmQuery()));
    queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        batchJobHistory = queryRun.get(tableNum(BatchJobHistory));

        if (batchJobHistory.RecId)
        {
            matched++;
        }
    }

    info(strFmt("@ConDemo:JobHistoryScanned", matched));
}
